// Precomputed AAlib character lookup tables
function base64ToUint16Array(b64: string): Uint16Array {
  const bin = typeof atob === "function" ? atob(b64) : Buffer.from(b64, "base64").toString("binary");
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Uint16Array(u8.buffer, u8.byteOffset, u8.byteLength / 2);
}

const TABLE_B64 = "";
const FILLTABLE_B64 = "";

export const AA_TABLE: Uint16Array = base64ToUint16Array(TABLE_B64);
export const AA_FILLTABLE: Uint16Array = base64ToUint16Array(FILLTABLE_B64);
